import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import ts from 'typescript';
const [repo, backup, ...files] = process.argv.slice(2);
const hash = value => crypto.createHash('sha256').update(value).digest('hex');
const relevantFlags = ts.NodeFlags.Let | ts.NodeFlags.Const | ts.NodeFlags.Using | ts.NodeFlags.AwaitUsing | ts.NodeFlags.OptionalChain;
function canonical(node) {
  if (ts.isParenthesizedExpression(node)) return canonical(node.expression);
  const result = { kind: ts.SyntaxKind[node.kind] };
  const flags = node.flags & relevantFlags;
  if (flags) result.semanticFlags = flags;
  if (ts.isExpressionStatement(node)) result.directiveEligible = ts.isStringLiteral(node.expression);
  for (const key of ['text', 'escapedText', 'rawText', 'operator', 'keywordToken', 'isTypeOnly', 'isExportEquals', 'templateFlags']) {
    if (key === 'text' && ts.isSourceFile(node)) continue;
    if (node[key] !== undefined) result[key] = node[key];
  }
  for (const key of Object.keys(node).sort()) {
    if (['parent', 'original', 'emitNode', 'jsDoc'].includes(key)) continue;
    const value = node[key];
    if (value && typeof value === 'object' && typeof value.kind === 'number' && typeof value.pos === 'number') result[key] = canonical(value);
    else if (Array.isArray(value) && value.some(child => child && typeof child.kind === 'number')) result[key] = value.map(child => canonical(child));
  }
  return result;
}
function comments(source) {
  const ranges = new Map();
  function walk(node) {
    for (const range of [...(ts.getLeadingCommentRanges(source.text, node.pos) || []), ...(ts.getTrailingCommentRanges(source.text, node.end) || [])]) ranges.set(range.pos + ':' + range.end, range);
    for (const child of node.getChildren(source)) walk(child);
  }
  walk(source);
  return [...ranges.values()].sort((a, b) => a.pos - b.pos).map(range => ({ kind: ts.SyntaxKind[range.kind], text: source.text.slice(range.pos, range.end).replace(/\s+/g, ' ').trim() }));
}
const rows = files.map(file => {
  const a = ts.createSourceFile(file, fs.readFileSync(path.join(backup, file), 'utf8'), ts.ScriptTarget.Latest, true, ts.ScriptKind.JS);
  const b = ts.createSourceFile(file, fs.readFileSync(path.join(repo, file), 'utf8'), ts.ScriptTarget.Latest, true, ts.ScriptKind.JS);
  const aa = JSON.stringify(canonical(a)), bb = JSON.stringify(canonical(b));
  const ac = JSON.stringify(comments(a)), bc = JSON.stringify(comments(b));
  return { path: file, parseDiagnosticsBefore: a.parseDiagnostics.map(d => ts.flattenDiagnosticMessageText(d.messageText, '\n')), parseDiagnosticsAfter: b.parseDiagnostics.map(d => ts.flattenDiagnosticMessageText(d.messageText, '\n')), canonicalASTSha256Before: hash(aa), canonicalASTSha256After: hash(bb), canonicalASTEqual: aa === bb, commentCountBefore: comments(a).length, commentCountAfter: comments(b).length, commentsSha256Before: hash(ac), commentsSha256After: hash(bc), actualCommentsEqual: ac === bc };
});
const passed = rows.every(row => !row.parseDiagnosticsBefore.length && !row.parseDiagnosticsAfter.length && row.canonicalASTEqual && row.actualCommentsEqual);
process.stdout.write(JSON.stringify({ typescriptVersion: ts.version, passed, files: rows }, null, 2) + '\n');
process.exitCode = passed ? 0 : 1;
